let historyPanelContext=null;
function historyPanelList(){const c=historyPanelContext;return c.kind==='srs'?(sectionVersions[c.key]||[]):(projectHistory[c.key]||[]);}
function drawHistoryPanel(){const box=document.getElementById('modal'),c=historyPanelContext,list=historyPanelList();box.className='version-history-drawer';box.innerHTML='<header class="version-drawer-heading"><h2>History</h2><button aria-label="Close history" onclick="document.getElementById(\'modal\').close()">×</button></header><p class="version-drawer-context">'+esc(c.title)+'</p><label class="version-history-sort"><span>◷</span><select aria-label="Sort history" onchange="historyPanelContext.oldest=this.value===\'oldest\';drawHistoryPanel()"><option value="newest">Last modified</option><option value="oldest" '+(c.oldest?'selected':'')+'>Oldest first</option></select></label><div class="version-history-list">'+list.map((v,i)=>({v,i})).sort((a,b)=>c.oldest?a.i-b.i:b.i-a.i).map(({v,i})=>'<article class="version-timeline-item '+(i===list.length-1?'current':'')+'"><span class="version-timeline-dot"></span><div class="version-item-heading"><strong>'+esc(v.label||new Date(v.time).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))+'</strong>'+(i===list.length-1?'<span class="version-current">Current</span>':'')+'<details class="version-item-menu"><summary aria-label="Version actions">⋮</summary><div><button onclick="renameHistoryItem('+i+')">Rename</button>'+(c.kind==='srs'?'<button '+(current().approved||i===list.length-1?'disabled':'')+' onclick="restoreSectionVersion('+i+')">Restore this version</button>':'')+'</div></details></div><time>'+new Date(v.time).toLocaleDateString()+'</time><p>By '+esc(v.author)+'</p><small>'+esc(v.reason||'Saved changes')+'</small><div id="versionRename'+i+'"></div></article>').join('')+'</div><footer class="version-drawer-footer">History is kept in this browser session.</footer>';if(!box.open)box.showModal();}
function renameHistoryItem(i){document.querySelectorAll('.version-item-menu').forEach(x=>x.open=false);const v=historyPanelList()[i],el=document.getElementById('versionRename'+i);el.innerHTML='<form class="version-rename" onsubmit="saveHistoryName(event,'+i+')"><input name="name" maxlength="80" required aria-label="Version name" value="'+esc(v.label||'Version '+(i+1))+'"><button>Save</button><button type="button" onclick="drawHistoryPanel()">Cancel</button></form>';el.querySelector('input').focus();}
function saveHistoryName(e,i){e.preventDefault();const value=new FormData(e.target).get('name').trim();if(!value)return;historyPanelList()[i].label=value;drawHistoryPanel();}
showProjectHistory=function(route){captureReq();captureProjectVersion(route);historyPanelContext={kind:'project',key:selected+':'+route,title:pageNames[route]||route};drawHistoryPanel();};
showSectionVersions=function(){sectionSave();historyPanelContext={kind:'srs',key:sectionKey(),title:sectionTitles[sectionIndex]};drawHistoryPanel();};
Object.assign(localizedLabels,{'History':'履歴','Last modified':'最終更新','Oldest first':'古い順','Current':'現在','Rename':'名前を変更','Restore this version':'このバージョンを復元','History is kept in this browser session.':'履歴はこのブラウザセッションに保存されます。'});
